#[derive(Clone, serde::Serialize, serde::Deserialize)]
#[php_class]
#[php(name = "HtmlToMarkdown\\ConversionResult")]
#[serde(default)]
pub struct ConversionResult {
    /// Converted text output in the selected format: Markdown, Djot, or plain text.
    #[php(prop, name = "content")]
    pub content: Option<String>,
    /// Structured document tree with semantic elements.
    ///
    /// Populated when `ConversionOptions.include_document_structure` is `true`. `None`
    /// otherwise (the default), which avoids the overhead of building the tree.
    ///
    /// When present, the tree mirrors the converted document: headings open
    /// `Group` sections, paragraphs and list items carry
    /// inline `TextAnnotation`s, and tables reference the same
    /// `TableGrid` data exposed in `Self.tables`.
    ///
    /// Note: this field is independent of the `metadata` feature flag. Document structure
    /// collection is always available at runtime; it is gated only by the runtime option, not
    /// by a compile-time feature.
    pub document: Option<DocumentStructure>,
    /// Extracted HTML metadata (title, OG, links, images, structured data).
    pub metadata: HtmlMetadata,
    /// Extracted tables with structured cell data and markdown representation.
    ///
    /// Table data is collected by the same pass that builds `Self.document`, so it is
    /// populated only when `ConversionOptions.include_document_structure` is `true`. With the
    /// default options this is an empty vec even for input that contains tables — the tables
    /// still appear in `Self.content` as rendered Markdown.
    pub tables: Vec<TableData>,
    /// Non-fatal processing warnings.
    pub warnings: Vec<ProcessingWarning>,
}

impl Default for ConversionResult {
    fn default() -> Self {
        <html_to_markdown_rs::ConversionResult as Default>::default().into()
    }
}

#[php_impl]
impl ConversionResult {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        tables: &ext_php_rs::types::ZendHashTable,
        warnings: &ext_php_rs::types::ZendHashTable,
        content: Option<String>,
        document: Option<&DocumentStructure>,
    ) -> PhpResult<Self> {
        let mut tables_core_result: Vec<TableData> = Vec::new();
        for (_, item) in tables.iter() {
            if let Some(parsed) = <&TableData as ext_php_rs::convert::FromZval>::from_zval(item) {
                tables_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to TableData".to_string(),
                ));
            }
        }
        let tables_core: Vec<TableData> = tables_core_result;
        let mut warnings_core_result: Vec<ProcessingWarning> = Vec::new();
        for (_, item) in warnings.iter() {
            if let Some(parsed) = <&ProcessingWarning as ext_php_rs::convert::FromZval>::from_zval(item) {
                warnings_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to ProcessingWarning".to_string(),
                ));
            }
        }
        let warnings_core: Vec<ProcessingWarning> = warnings_core_result;
        Ok(Self {
            content,
            document: document.cloned(),
            metadata: Default::default(),
            tables: tables_core,
            warnings: warnings_core,
        })
    }

    pub fn get_content(&self) -> Option<String> {
        self.content.clone()
    }

    pub fn get_document(&self) -> Option<DocumentStructure> {
        self.document.clone().map(Into::into)
    }

    pub fn set_document(&mut self, value: Option<&DocumentStructure>) {
        self.document = value.map(|value| value.clone().into());
    }

    pub fn get_metadata(&self) -> HtmlMetadata {
        self.metadata.clone()
    }

    pub fn get_tables(&self) -> Vec<TableData> {
        self.tables.clone()
    }

    pub fn get_warnings(&self) -> Vec<ProcessingWarning> {
        self.warnings.clone()
    }
}

