#[derive(Clone, serde::Serialize, serde::Deserialize)]
#[php_class]
#[php(name = "HtmlToMarkdown\\TableGrid")]
#[serde(default)]
#[allow(clippy::similar_names)]
pub struct TableGrid {
    /// Number of rows.
    #[php(prop, name = "rows")]
    pub rows: u32,
    /// Number of columns.
    #[php(prop, name = "cols")]
    pub cols: u32,
    /// All cells in the table as a flat, sparse list.
    ///
    /// The list is ordered by `(row, col)` but is **not** a dense `rows × cols` matrix: cells
    /// that are covered by a spanning cell (via `row_span > 1` or `col_span > 1`) do not appear
    /// in the list. Only the top-left "origin" cell of a span is present, with its `row_span`
    /// and `col_span` fields set accordingly.
    ///
    /// To reconstruct the full visual grid, iterate over all cells and mark the rectangular
    /// region `[row .. row+row_span, col .. col+col_span]` as occupied by that cell. Any
    /// `(row, col)` position that is not the origin of any cell is covered by a span from an
    /// earlier cell.
    ///
    /// The length of this vec is `≤ rows * cols`. An empty table (`rows == 0 || cols == 0`)
    /// produces an empty vec.
    pub cells: Vec<GridCell>,
}

impl Default for TableGrid {
    fn default() -> Self {
        <html_to_markdown_rs::TableGrid as Default>::default().into()
    }
}

#[php_impl]
impl TableGrid {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(rows: u32, cols: u32, cells: &ext_php_rs::types::ZendHashTable) -> PhpResult<Self> {
        let mut cells_core_result: Vec<GridCell> = Vec::new();
        for (_, item) in cells.iter() {
            if let Some(parsed) = <&GridCell as ext_php_rs::convert::FromZval>::from_zval(item) {
                cells_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to GridCell".to_string(),
                ));
            }
        }
        let cells_core: Vec<GridCell> = cells_core_result;
        Ok(Self {
            rows,
            cols,
            cells: cells_core,
        })
    }

    pub fn get_rows(&self) -> u32 {
        self.rows.clone()
    }

    pub fn get_cols(&self) -> u32 {
        self.cols.clone()
    }

    pub fn get_cells(&self) -> Vec<GridCell> {
        self.cells.clone()
    }
}

