#[php_class]
#[php(name = "HtmlToMarkdown\\VisitResult")]
#[derive(Clone, Default, serde::Serialize, serde::Deserialize)]
#[serde(default)]
pub struct VisitResult {
    #[serde(rename = "type")]
    type_tag: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub custom: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error: Option<String>,
}

#[php_impl]
impl VisitResult {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        let value: Self = serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))?;
        if !matches!(
            value.type_tag.as_str(),
            "continue" | "custom" | "skip" | "preserve_html" | "error"
        ) {
            return Err(PhpException::from_message(format!(
                "Invalid VisitResult tag: {}",
                value.type_tag,
            )));
        }
        Ok(value)
    }

    #[php(getter, change_case = "snake_case")]
    pub fn get_type_tag(&self) -> String {
        self.type_tag.clone()
    }

    #[php(getter, change_case = "snake_case")]
    pub fn get_custom(&self) -> Option<String> {
        self.custom.clone()
    }

    #[php(getter, change_case = "snake_case")]
    pub fn get_error(&self) -> Option<String> {
        self.error.clone()
    }
}

