/// Convert a `html_to_markdown_rs::error::ConversionError` error to a PHP exception.
#[allow(dead_code)]
fn conversion_error_to_php_err(e: html_to_markdown_rs::error::ConversionError) -> ext_php_rs::exception::PhpException {
    let msg = e.to_string();
    #[allow(unreachable_patterns)]
    match &e {
        html_to_markdown_rs::error::ConversionError::ParseError(..) => {
            ext_php_rs::exception::PhpException::from_message(format!("[ParseError] {}", msg))
        }
        html_to_markdown_rs::error::ConversionError::SanitizationError(..) => {
            ext_php_rs::exception::PhpException::from_message(format!("[SanitizationError] {}", msg))
        }
        html_to_markdown_rs::error::ConversionError::ConfigError(..) => {
            ext_php_rs::exception::PhpException::from_message(format!("[ConfigError] {}", msg))
        }
        html_to_markdown_rs::error::ConversionError::IoError(..) => {
            ext_php_rs::exception::PhpException::from_message(format!("[IoError] {}", msg))
        }
        html_to_markdown_rs::error::ConversionError::Panic(..) => {
            ext_php_rs::exception::PhpException::from_message(format!("[Panic] {}", msg))
        }
        html_to_markdown_rs::error::ConversionError::InvalidInput(..) => {
            ext_php_rs::exception::PhpException::from_message(format!("[InvalidInput] {}", msg))
        }
        html_to_markdown_rs::error::ConversionError::InputTooLarge { .. } => {
            ext_php_rs::exception::PhpException::from_message(format!("[InputTooLarge] {}", msg))
        }
        html_to_markdown_rs::error::ConversionError::Other(..) => {
            ext_php_rs::exception::PhpException::from_message(format!("[Other] {}", msg))
        }
        _ => ext_php_rs::exception::PhpException::from_message(msg),
    }
}

